#include "resident/kernel/common_fact_prefix.hpp"
// 冷返报必须追到本Task的实交、原结酬与Common事实次序；报告只让当场两人知情。
#include "task_message_report.hpp"
#include "resident/domains/tasks/personal_reports/task_personal_report.hpp"
#include <charconv>
#include <limits>
